function dir$dmnhomvb(p){
  this.constructor(p);
}
dir$dmnhomvb.prototype = new DirEvent();
dir$dmnhomvb.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmnhomvb.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()
dir$dmnhomvbDisabledMasterField(p, g);
}

function dir$dmnhomvbDisabledMasterField(p){
var maNhom = p.valForm('ma_nvb');
	if(maNhom) {
		p.setDisabled('ma_nvb', true);
	} else {
		p.setDisabled('ma_nvb', false);
	}
}






